assert len(re.findall(r'^\| L\d{3} \|', (p/'local-seo-queries-200.md').read_text(),re.M))==200
js=re.findall(r'<script>(.*?)</script>',html,re.S)[0];Path('/tmp/letsaimit-local-report.js').write_text(js)
print(json.dumps({'embedded_rows':len(embedded['queries']),'embedded_matches_json':True,'markdown_query_links':200,'output_html_bytes':len(html.encode()),'publication_state':'published' if published else 'planned'},indent=2))
